+        let short = feed((0.0, 0.0, 0.0), (0.0002, 0.0, 0.0));
+        let arc = feed((0.0002, 0.0, 0.0), (2.0002, 0.0, 0.0)).with_arc(crate::geo2d::Point2::new(1.0002, 0.0), true);
